#include <vector>
#include <algorithm>

int main() {
    std::vector<int> v = {1, 2, 3, 4, 5};

    // O(N) operation: Shift 4 elements (3, 4, 5, 6)
    v.insert(v.begin() + 1, 6); 
    // v is now {1, 6, 2, 3, 4, 5}

    // O(N) operation: Shift 4 elements (3, 4, 5)
    v.erase(v.begin() + 2); 
    // v is now {1, 6, 3, 4, 5}

    // O(1) amortized operation
    v.push_back(7); 
}
